public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersection coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the paths between adjacent n-tersections are valid
    for (int[] path : paths) {
        if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n) {
            return "cannot be travelled";
        }
    }

    // Check if the starting n-tersection is connected to the ending n-tersection
    boolean[] visited = new boolean[n * n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0] * n + start[1]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1]) {
                int[] next = new int[] {path[2], path[3]};
                if (!visited[next[0] * n + next[1]]) {
                    queue.add(next);
                    visited[next[0] * n + next[1]] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}
