    int numToRemove = (int) Math.ceil(arr.length * 0.05);

    // Remove the smallest and largest elements from the array
    int[] trimmedArr = Arrays.copyOfRange(arr, numToRemove, arr.length - numToRemove);

    // Calculate the mean of the remaining elements
    double mean = Arrays.stream(trimmedArr).average().getAsDouble();

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000.0;
